    def listes_vers_matrice(G: list) -> list:
    """Matrice d'adjacence du graphe de listes d'adjacence G."""
    n = len(G)
    M = [[0] * n for i in range(n)]    # n lignes indépendantes
    for u in range(n):
        for v in G[u]:
            M[u][v] = 1
    return M

def matrice_vers_listes(M: list) -> list:
    """Listes d'adjacence du graphe de matrice d'adjacence M."""
    n = len(M)
    G = [[] for i in range(n)]
    for u in range(n):
        for v in range(n):
            if M[u][v] == 1:
                G[u].append(v)
    return G

