  Pour le maximum, il n'y a pas de sortie anticipée possible : la plus grande valeur peut se trouver dans la dernière case. On parcourt donc toute la liste en tenant à jour le meilleur candidat rencontré jusque-là.

def maximum(t):
    # t : liste non vide ; renvoie sa plus grande valeur
    m = t[0]
    for i in range(1, len(t)):
        if t[i] > m:
            m = t[i]
    return m

def indice_max(t):
    # t non vide ; indice de la 1re occurrence du maximum
    im = 0
    for i in range(1, len(t)):
        if t[i] > t[im]:
            im = i
    return im
